#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Max-reduction over the middle dimension of a contiguous 3D tensor [B, R, N].
// Output shape: [B, N]. Optimization: split the R reduction across 4
// consecutive lanes per output column; each lane reduces R/4 rows with 8
// independent accumulators, then the 4 partial maxima are combined with warp
// shuffles (no shared memory, no __syncthreads). A warp covers 8 consecutive
// columns x 4 R-slices, so every load still reads full 32-byte sectors while
// the 4x larger thread count improves latency hiding and load balance.
template <typename T>
__global__ void max_reduce_middle_kernel(const T* __restrict__ X,
                                         T* __restrict__ Y,
                                         int B, int R, int N)
{
  const T neg_inf = -std::numeric_limits<T>::infinity();
  const int64_t g = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  const int slice = (int)(g & 3);
  const int c = (int)(g >> 2);
  const int b = c / N;
  const int col = c - b * N;
  const int len = (R + 3) >> 2;
  const int r_beg = slice * len;
  const int r_end = ::min(r_beg + len, R);
  T acc0 = neg_inf, acc1 = neg_inf, acc2 = neg_inf, acc3 = neg_inf;
  T acc4 = neg_inf, acc5 = neg_inf, acc6 = neg_inf, acc7 = neg_inf;
  if (b < B) {
    Tensor mX = make_tensor(make_gmem_ptr(X + (int64_t)b * R * N),
                            make_shape(R, N),
                            make_stride(N, Int<1>{}));
    int r = r_beg;
    for (; r + 7 < r_end; r += 8) {
      acc0 = ::max(acc0, mX(r + 0, col));
      acc1 = ::max(acc1, mX(r + 1, col));
      acc2 = ::max(acc2, mX(r + 2, col));
      acc3 = ::max(acc3, mX(r + 3, col));
      acc4 = ::max(acc4, mX(r + 4, col));
      acc5 = ::max(acc5, mX(r + 5, col));
      acc6 = ::max(acc6, mX(r + 6, col));
      acc7 = ::max(acc7, mX(r + 7, col));
    }
    for (; r < r_end; ++r) {
      acc0 = ::max(acc0, mX(r, col));
    }
  }
  acc0 = ::max(acc0, acc1);
  acc2 = ::max(acc2, acc3);
  acc4 = ::max(acc4, acc5);
  acc6 = ::max(acc6, acc7);
  acc0 = ::max(acc0, acc2);
  acc4 = ::max(acc4, acc6);
  T res = ::max(acc0, acc4);
  res = ::max(res, __shfl_xor_sync(0xffffffffu, res, 1));
  res = ::max(res, __shfl_xor_sync(0xffffffffu, res, 2));
  if (slice == 0 && b < B) {
    Tensor mY = make_tensor(make_gmem_ptr(Y + (int64_t)b * N),
                            make_shape(N),
                            make_stride(Int<1>{}));
    mY(col) = res;
  }
}
torch::Tensor max_reduce_dim(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(x.dim() == 3, "x must be 3D [B, R, N]");
  if (dim < 0) dim += x.dim();
  TORCH_CHECK(dim == 1, "custom kernel currently reduces over dim == 1");
  auto x_c = x.contiguous();
  const int64_t B = x_c.size(0);
  const int64_t R = x_c.size(1);
  const int64_t N = x_c.size(2);
  auto y = torch::empty({B, N}, x_c.options());
  constexpr int Threads = 256;
  dim3 block(Threads);
  const int64_t work_items = B * N * 4;
  const int64_t blocks = (work_items + Threads - 1) / Threads;
  TORCH_CHECK(blocks <= 0x7fffffff, "invalid grid size");
  if (blocks == 0) {
    return y;
